{"rob": "robolang 1.3;

task transfer(robot r, object v1, object v2, location bench_loc, location centrifuge_loc, location fridge_loc) {
    goal { object_at v1 centrifuge_loc; holding r v2; robot_at r bench_loc; }
    plan {
        move r to bench_loc;
        grasp r v1;
        move r to centrifuge_loc;
        place r v1 at centrifuge_loc;
        move r to fridge_loc;
        grasp r v2;
        move r to bench_loc;
    }
}
", "task": "transfer", "bindings": [{"param": "r", "id": "arm1"}, {"param": "v1", "id": "vial1"}, {"param": "v2", "id": "vial2"}, {"param": "bench_loc", "id": "bench"}, {"param": "centrifuge_loc", "id": "centrifuge"}, {"param": "fridge_loc", "id": "fridge"}]}
